Definition source_AST_155_0002 := row_to_tm [t1LB;t0LA;t1RC;t0LB;t1LA;t0RD;t1RC;t0RC].
Definition perm_AST_155_0002(q:St):St := match q with StA=>StC | StB=>StD | StC=>StB | StD=>StA end.
Definition family_AST_155_0002(x:{c:cconf | bj_mark c}):cconf := proj1_sig x.
Definition boot_AST_155_0002:{c:cconf | bj_mark c}.
Proof.
 exists(StA,(rep[S1]1,S1,bj_guard)).
 apply bj_anchor,bj_suffix_guard.
Defined.
Definition skip_AST_155_0002(t:Instr):bool := instr_eqb t (StC,S1) || instr_eqb t (StD,S1) || instr_eqb t (StA,S0).

(* spec 1RB0LA_1LC0RD_1LA0LC_1RB0RB *)
Definition r_AST_155_0000 : list (option Trans) := [t1RB;t0LA;t1LC;t0RD;t1LA;t0LC;t1RB;t0RB].
Lemma cv_AST_155_0000 : coversTr (row_to_tm r_AST_155_0000).
Proof. assert(Hprogress:forall x,exists y,
    Reach1 source_AST_155_0000(family_AST_155_0000 x)(family_AST_155_0000 y)).
  { intros[c Hc]. destruct(bj_return source_AST_155_0000 eq_refl eq_refl eq_refl eq_refl
      eq_refl eq_refl eq_refl eq_refl c Hc)as(d&Hd&Hrun).
    exists(exist bj_mark d Hd);exact Hrun. }
  assert(Hrec:forall q,In q [(StA,S1);(StB,S1);(StD,S0)]->
    forall N,exists j,N<=j /\ FiresAt(row_to_tm r_AST_155_0000)(perm_AST_155_0000(fst q),snd q)j).
  { intros q Hq. apply(conjugate_marked_return_fire source_AST_155_0000 _ perm_AST_155_0000 false
      _ family_AST_155_0000 q 15 boot_AST_155_0000).
    - intros[] [];reflexivity.
    - rewrite <-lift_c0. apply csteps_lift. vm_compute;reflexivity.
    - exact Hprogress.
    - intros[c Hc]. destruct Hq as[<-|[<-|[<-|[]]]].
      + apply fires_here;apply bj_mark_instr;exact Hc.
      + apply bj_mark_B;try reflexivity;exact Hc.
      + apply bj_mark_D;try reflexivity;exact Hc. }
  apply coversTr_nqh,neverqhtr_mirror.
  apply(ngram_check_neverqh_fuelmixtr_except_sound _ 4 0 12040 36
    skip_AST_155_0000 cert_AST_155_0000).
  - intros[[] []] H N;try discriminate.
    destruct(Hrec (StB,S1) ltac:(simpl;tauto) N)as(j&Hj&Hf); exists j;split;[exact Hj|apply mirror_fires;exact Hf].
    destruct(Hrec (StA,S1) ltac:(simpl;tauto) N)as(j&Hj&Hf); exists j;split;[exact Hj|apply mirror_fires;exact Hf].
    destruct(Hrec (StD,S0) ltac:(simpl;tauto) N)as(j&Hj&Hf); exists j;split;[exact Hj|apply mirror_fires;exact Hf].
  - vm_compute;reflexivity. Qed.

